<span class="line"><span style="color:#C792EA;">let</span><span style="color:#BABED8;"> scores </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> [</span><span style="color:#F78C6C;">85</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;"> 92</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;"> 78</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;"> 90</span><span style="color:#89DDFF;">,</span><span style="color:#F78C6C;"> 88</span><span style="color:#BABED8;">]</span><span style="color:#89DDFF;">;</span></span>
